/*
ClassMethod ParseX12(fileStream As %Stream.GlobalCharacter, ByRef source)
{
	#dim source As EnsLib.EDI.X12.Document

	// $$$TRACE( "Stream length: " _ fileStream.Size)

	set x12Data = ""
	do
	{
		set len = 32000
		set x12Data = x12Data _ fileStream.Read(.len, .sc)

	} while(len >= 0 && sc = 1)


    Try {
		set source = ##class(EnsLib.EDI.X12.Document).ImportFromString(x12Data)
		 }
	 Catch thrownErr {
		If $ZE="" {
			Set tSC=thrownErr.AsStatus()
			$$$LOGERROR( "Error: " _ tSC)
		} Else {
			Set tSC=##class(Ens.Util.Error).EnsSystemError($classname(),"Transform")
			$$$LOGERROR(  "System Error: " _ tSC)
		}
	}
}*/

Method.Implementation:

		$$$TRACE( " *** GetISA *** ")
    Try {

		 if ( ($ISOBJECT(source)) && (source.%Extends("EnsLib.EDI.X12.Document")) )
		 {

				Set tBlankSrc=1, source.DocType="HIPAA_5010:Interchange:Group" 
				$$$TRACE( " *** GetISA *** - Source is an X12. Now looping through segment to find ISA and IEA")

			// $$$TRACE("ISA - IDs: " _ source.GetValueAt("ISA:InterchangeReceiverId")   _" -> " _ source.GetValueAt("ISA:InterchangeReceiverID"))


			// WRITE !, source.Name _" # of Children " _ source.ChildCount  _" # of segments: " _ source.SegCountGet() 
			#dim seg As EnsLib.EDI.X12.Segment 

			for segNum=1:1:source.SegCountGet()
			{
				$$$TRACE( " *** GetISA *** Segment Number" _ segNum )
				set seg = source.GetSegmentAt(segNum)
				$$$TRACE( " *** GetISA *** segment: " _ seg)
				set segPath = source.GetSegmentPath(segNum, .segStat)

				set stat = seg.GetContentArray(.pContents,"source", "HIPAA_5010:" _ seg.Name)
				if $$$ISERR(stat)
				{
					$$$TRACE( "Error in GetContentArray: " _ stat)
					return
				}
				if (segPath [ "ISA")
				{		
					Do interchange.SetAt(seg, 1)
					$$$TRACE( " *** GetISA *** Set ISA")
				}
				elseif (segPath [ "IEA")
				{		
					Do interchange.SetAt(seg, 2)
					$$$TRACE( " *** GetISA *** Set IEA")
				}

			}
		 }
		 else
		 {
			 $$$TRACE( " *** GetISA *** - Source is either not an object or not of type EnsLib.EDI.X12.Document")
		 }
	 }
	 Catch thrownErr {
		If $ZE="" {
			Set tSC=thrownErr.AsStatus()
			$$$LOGERROR( "GetISA Error: " _ tSC)
		} Else {
			Set tSC=##class(Ens.Util.Error).EnsSystemError($classname(),"Transform")
			$$$LOGERROR( "GetISA System Error: " _ tSC)
		}
	}

	Set k1="",tSC=1

	$$$TRACE( " *** GetGS *** ")

	if ( ($ISOBJECT(source)) && (source.%Extends("EnsLib.EDI.X12.Document")) )
	{
		Do
		{	
			Set tBlankSrc=1, source.DocType="HIPAA_5010:Interchange:Group" 				

			Set k1=source.NextChild(k1,source.GetSegmentIndex("GroupDocsRef",.tSCTrans))
			if ('$IsObject(k1))
			{
				// WRITE !, "-- No more FunctionalGroups --"

				QUIT
			}
			Set source.FunctionalGroups(k1)=k1
			If ""=k1.DocType {
				Set tDocType = k1.resolveChildDocType()
				Set tSC =k1.PokeDocType(tDocType)
			}
			Set tSC =source.FunctionalGroups(k1).BuildMap()
			if $$$ISERR(tSC)
			{
				$$$TRACE( "FunctionalGroups BuildMap: " _ tSC)
				return
			}
			#dim gsSeg As EnsLib.EDI.X12.Segment 						
			For si=1:1:source.FunctionalGroups(k1).SegCount 
	        {
		        set gsSeg = source.FunctionalGroups(k1).GetSegmentAt(si)
				set gsSegPath = source.FunctionalGroups(k1).GetSegmentPath(si, .gsSegStat)

				// WRITE !, gsSeg.OutputToString() _" -->" _ gsSeg.DocType
				if (gsSegPath [ "GS") 
				{

					Do group.SetAt(gsSeg, 1)
				}
				elseif (gsSegPath [ "GE")
				{
					set sg2 = gsSeg.%ConstructClone(1)
					Do sg2.SetValueAt("x", "1","set","")
					Do group.SetAt(sg2, 2)

					// WRITE !, sg2.DocType _": " _ sg2.OutputToString()
				}			 

        	}
		}while ($IsObject(k1))
	}

	Set k1="",tSC=1

	$$$TRACE( " *** GetST *** ")

	if ( ($ISOBJECT(source)) && (source.%Extends("EnsLib.EDI.X12.Document")) )
	{

	Set tBlankSrc=1, source.DocType="HIPAA_5010:Interchange:Group" 				

	For {
		Set k1=source.NextChild(k1,source.GetSegmentIndex("GroupDocsRef",.tSCTrans))
		if ('$IsObject(k1))
		{
			// WRITE !, "-- No more FunctionalGroups --"

			QUIT
		}
		Set source.FunctionalGroups(k1)=k1
		If ""=k1.DocType {
			Set tDocType = k1.resolveChildDocType()
			Set tSC =k1.PokeDocType(tDocType)
		}
		Set tSC =source.FunctionalGroups(k1).BuildMap()
		if $$$ISERR(tSC)
		{
			$$$TRACE( "FunctionalGroups BuildMap: " _ tSC)
			return
		}


		For i=1:1:source.FunctionalGroups(k1).ChildCount
        { 
          #dim individualST As EnsLib.EDI.X12.Document
          set individualST = source.FunctionalGroups(k1).getNthChild(i,2)
          If ""=individualST.DocType {
			Set tDocType = individualST.resolveChildDocType()
			Set tSC =individualST.PokeDocType(tDocType)
		 }
		 Set tSC =individualST.BuildMap()
		if $$$ISERR(tSC)
		{
			$$$TRACE( "FunctionalGroups BuildMap: " _ tSC)
			return
		}

           // WRITE !, i _". " _ individualST.DocType // _ "= " _ individualST.OutputToString()


	        set refGroupIDind=individualST.GetSegmentIndex("TRN",.refGroupIDstatus)  
	        set GroupID=individualST.GetValueAt(refGroupIDind_":2")
	        set stCtrlNum = individualST.GetValueAt("1:2")

	        set st2 = individualST.%ConstructClone(1)

	        $$$TRACE("   ST: " _ stCtrlNum _ ": " _ GroupID _", count: " _ individualST.SegCount _", size: " _ individualST.FullSize _ ", ST2 size: " _ st2.FullSize)

	        Do ST.SetAt(st2 , GroupID)

        }  
	}
	}

$$$TRACE(" MergeSTs: interchange.Count:: "_interchange.Count()) if (interchange.Count() > 1) { #dim isaDoc As EnsLib.EDI.X12.Segment set isaDoc = interchange.GetAt(1) set tSC = isaDoc.DocTypeSet("HIPAA_5010:ISA") set isaUniqId = $ZSTRIP(isaDoc.GetValueAt("InterchangeSenderId"), "*W") _"-" _ $ZSTRIP(isaDoc.GetValueAt("InterchangeReceiverID"), "*W") _"-" _ $ZSTRIP(isaDoc.GetValueAt("InterchangeControlNumber"), "*W")
$$$TRACE(ST.Count()) if (ST.Count() > 1) {
$$$TRACE(x12Rec.CKPYREFID _", " _ isaUniqId _ " ---> Merge: " _ ST.Count() _" STs") #dim X12stream As %Stream.GlobalCharacter set X12stream = ##class(%Stream.GlobalCharacter).%New() Do X12stream.Write(isaDoc.OutputToString()) Do X12stream.Write(group.GetAt(1).OutputToString()) set st = "" for i=1:1:ST.Count() { #dim str As EnsLib.EDI.X12.Document set str = ST.GetNext(.st)
set stat = str.SetValueAt("000"_i, "1:2" ,"set","") // WRITE !, "Set ST control number: " _ stat _ ", ST size: " _ str.FullSize) // $$$TRACE( "New ST control number: " _ str.GetValueAt("1:2")) Do X12stream.Write(str.OutputToString()) } //# Copy GS(1): Number of Transaction Sets Do group.GetAt(2).SetValueAt(ST.Count(),"1") Do X12stream.Write(group.GetAt(2).OutputToString()) Do X12stream.Write(interchange.GetAt(2).OutputToString())
$$$TRACE(isaUniqId _", --- Merged Stream size: " _ X12stream.Size)
set newX12Rec = ##class(IHC.ITF.DStruc.DndCoreEraX12Record).%New() set newX12Rec.Status = "Processed-Batched" set newX12Rec.X12stream = X12stream set newX12Rec.ReceiverId= x12Rec.ReceiverId set newX12Rec.CKPYREFID = x12Rec.CKPYREFID set newX12Rec.CreateTime = $ZDATETIME($HOROLOG,3, 1) set newX12Rec.Route = $PIECE(tpInfo, "#", 1) set newX12Rec.TpLinkId = $PIECE(tpInfo, "#", 2) set newX12Rec.SNIP = $PIECE(tpInfo, "#", 3) set newX12Rec.IsaUniqId = isaUniqId Do newX12Rec.%Save() set x12Rec.Status = "Merged" // Original X12 is marked merged } else { $$$TRACE(isaUniqId _ " ---> Single" ) set x12Rec.Status = "Processed-Single" set x12Rec.Route = $PIECE(tpInfo, "#", 1) set x12Rec.TpLinkId = $PIECE(tpInfo, "#", 2) set x12Rec.SNIP = $PIECE(tpInfo, "#", 3) set x12Rec.IsaUniqId = isaUniqId } if (x12Rec.CKPYREFID '= "") { Do x12Rec.%Save() } }

	set retStr = ""
	 Set rs = ##class(%SQL.Statement).%ExecDirect(,"SELECT lnk.ID, lnk.NAME, lnk.SNIP " _
 "FROM IHC_TPManage.TRADELINKS lnk, IHC_TPManage.TPIDS tp, IHC_TPManage.TRANSACTIONTYPES tt " _
 "where tp.ID = lnk.IsaReceiverId and tt.TransactionSetId = '835' AND tt.ID = lnk.TRANSTYPE " _
 "AND tp.TPID = '" _ tpId _ "' " )

	While rs.%Next() {
		set nm = rs.%Get("NAME")
		set id = rs.%Get("ID")
		// $$$TRACE("TP Link: " _ nm _", Id: " _ id)	

		Set tpLink = ##class(IHC.TPManage.TRADELINKS).%OpenId(id)
		if ($IsObject(tpLink))
		{
		 set retStr = tpLink.Routing _ "#" _id _"#" _ rs.%Get("SNIP")


		 Set tSet="",tId=""
			For {
				Set tSet = tpLink.customProp.GetNext(.tId)
				Quit:""=tId
				if (tSet.Key = "BatchingMode835")
				{
					set retStr = retStr _ "#" _tSet.Value

					QUIT
				}
			}

		}
		else
		{
		 $$$LOGERROR( "Not an TRADELINKS object: " _ id)
		}
	}
	$$$TRACE("TP Link for " _ tpId _ ": " _ ", Return: " _ retStr)
	return retStr

	set x12Rec = ##class(IHC.ITF.DStruc.DndCoreEraX12Record).%OpenId(id)

   #dim x12Doc As EnsLib.EDI.X12.Document
	set x12Doc = ##class(EnsLib.EDI.X12.Document).ImportFromLibraryStream(x12Rec.X12stream)
 	if ( ($ISOBJECT(x12Doc)) && (x12Doc.%Extends("EnsLib.EDI.X12.Document")) )
 	{
   set tSC = ##class(IHC.ITF.ITFCOMMON.EdiX12utils).GetTpInformation(x12Doc, "Batch",  "Out", 999, 1, .fullErrorMsg, .tPrelationDocumentId, .parentErrorMsg ) 

   if ($$$ISERR(tSC))
   {
	 $$$TRACE( "Error from CallEdiX12Parser: "  _ fullErrorMsg _", tPrelationDocumentId: " _ tPrelationDocumentId _", ParentMsg: " _ parentErrorMsg)
	   set relDocObj = ##class(IHC.TPManage.TPrelationDocument).%OpenId(tPrelationDocumentId)
       if $IsObject(relDocObj)
       {
	   	  set dtTm = $ZDATETIME($HOROLOG,3, 1)
	   	  set str = x12Doc.OutputToString()

            set sqlStr = "INSERT into IHC_ITF_ITFCOMMON_X12.WorkFlow " _
		  " (InterchangeReceiverID, InterchangeSenderID, TransactionType, TransactionVersion, WorkStatus, ErrorType, Error, WorkUser, CreateDtTm, x12Data, OrigX12Id) " _
		  " values (?,?,?,?,?,?,?,?,?,?,?)"
		  #dim rset As %SQL.StatementResult
		  set rset = ##class(%SQL.Statement).%ExecDirect(, .sqlStr, relDocObj.ISARECEIVERTPID, relDocObj.ISASENDERTPID, relDocObj.TransactionCode, relDocObj.TransactionVersion, "New", "TP", fullErrorMsg , $USERNAME, dtTm, str, 0)
		  $$$TRACE("SQL code: " _ rset.%SQLCODE)
		  if (rset.%SQLCODE < 0)
		  {
			  return $$$ERROR($$$GeneralError, "SQL failed: " _ rset.%SQLCODE _"; " _ rset.%Message)
		  }
		  $$$TRACE( "Workflow Id: " _ rset.%ROWID)
       }
     }
   }
